#define OT_LEN 8
#define OT_SIZE (1<<OT_LEN)
#define PACKET_LEN 32768
typedef struct{DISPENV disp;DRAWENV draw;uint32_t ot[OT_SIZE];char packets[PACKET_LEN];}DB;
typedef enum{STATE_TITLE,STATE_PLAY,STATE_PAUSE,STATE_DIALOGUE,STATE_GAMEOVER,STATE_ENDING,STATE_CREDITS}GameState;
static DB db[2];static int active=0,font_id;static char*next_packet;static char pad_buffer[2][34];static uint16_t old_btn=0xffff;static GameState state=STATE_TITLE;
static int px=20,py=190,room=0,shards=0,timer_frames=60*60*5,health=3,anim_tick=0,walk_tick=0,facing=1,score=0,checkpoint_room=0,checkpoint_score=0,checkpoint_time=0,last_room=0,area_banner=0;
static uint8_t shard_taken[4]={0},puzzle_done[4]={0},echo_seen[4]={0};static int switch_a=0,switch_b=0,dialogue_id=0,invuln=0;static MokoGameplay gameplay;static MokoFinale finale;
static void sfx(int p){moko_audio_sfx(p);}
static void init(void){ResetGraph(0);InitGeom();EnterCriticalSection();InitPAD(pad_buffer[0],34,pad_buffer[1],34);StartPAD();ChangeClearPAD(0);ExitCriticalSection();SetDefDispEnv(&db[0].disp,0,0,320,240);SetDefDrawEnv(&db[0].draw,0,240,320,240);SetDefDispEnv(&db[1].disp,0,240,320,240);SetDefDrawEnv(&db[1].draw,0,0,320,240);db[0].draw.isbg=db[1].draw.isbg=1;setRGB0(&db[0].draw,6,7,15);setRGB0(&db[1].draw,6,7,15);PutDispEnv(&db[0].disp);PutDrawEnv(&db[0].draw);SetDispMask(1);FntLoad(960,0);font_id=FntOpen(8,8,304,54,0,256);ClearOTagR(db[0].ot,OT_SIZE);next_packet=db[0].packets;moko_sprite_init();moko_audio_init();gameplay_reset(&gameplay);finale_reset(&finale);}
static void rect(int x,int y,int w,int h,int r,int g,int b){TILE*p=(TILE*)next_packet;setTile(p);setXY0(p,x,y);setWH(p,w,h);setRGB0(p,r,g,b);addPrim(db[active].ot,p);next_packet+=sizeof(TILE);}static void frame(void){DrawSync(0);VSync(0);PutDispEnv(&db[active].disp);PutDrawEnv(&db[active].draw);DrawOTag(db[active].ot+OT_SIZE-1);active^=1;ClearOTagR(db[active].ot,OT_SIZE);next_packet=db[active].packets;anim_tick++;if(area_banner>0)area_banner--;}
static uint16_t buttons(void){PADTYPE*p=(PADTYPE*)pad_buffer[0];return p->stat==0?p->btn:0xffff;}static int pressed(uint16_t n,uint16_t k){return !(n&k)&&(old_btn&k);}static int hit(int a,int b,int c,int d,int e,int f,int g,int h){return a<e+g&&a+c>e&&b<f+h&&b+d>f;}static void say(int id){dialogue_id=id;state=STATE_DIALOGUE;}
static void reset_game(void){int i;px=20;py=190;room=0;last_room=0;shards=0;health=3;score=0;timer_frames=60*60*5;switch_a=switch_b=0;invuln=0;area_banner=100;checkpoint_room=0;checkpoint_score=0;checkpoint_time=timer_frames;gameplay_reset(&gameplay);finale_reset(&finale);for(i=0;i<4;i++){shard_taken[i]=0;puzzle_done[i]=0;echo_seen[i]=0;}moko_audio_set_room(0);sfx(0x1200);say(1);}
static void draw_moko(void){int i;if(gameplay.dash_timer>0){for(i=1;i<4;i++)rect(px-(facing?i*5:-i*5),py+5,8,10,25+i*10,70+i*15,95+i*20);}moko_sprite_draw(px,py,facing,walk_tick,invuln,anim_tick,db[active].ot,&next_packet);}static void draw_shard(int x,int y){int p=(anim_tick/8)&3;rect(x-2-p,y-5-p,13+p*2,24+p*2,25,75,90);rect(x,y,9,14,80,215,245);rect(x+2,y-4,5,4,190,250,255);rect(x+3,y+3,3,6,230,255,255);}static int hx(void){return 40+((anim_tick*2)%230);}static int hy(void){return 78+(anim_tick%115);}static int pulse_x(int seed){return 25+((anim_tick*(2+seed)+seed*71)%270);}
static void echo_art(void){int p=2+((anim_tick/10)&3);if(room<4&&!echo_seen[room]){int ex=55+room*38,ey=112+room*17;rect(ex-p,ey-p,12+p*2,12+p*2,22,55,75);rect(ex,ey,12,12,95,175,205);rect(ex+4,ey+3,4,6,205,240,245);}}
static void station_art(void){int i;rect(0,58,320,164,13,18,35);rect(0,194,320,28,28,34,52);rect(0,218,320,4,95,84,70);for(i=0;i<5;i++){int x=18+i*68;rect(x,72,48,34,20,35,62);rect(x+3,75,42,28,32,48,78);rect(x+5,78,38,2,105,125,150);}rect(92,114,136,7,65,76,100);rect(112,180,18,28,85,100,150);rect(116,185,10,8,180,200,230);rect(151,124,18,18,205,190,130);rect(158,127,2,7,55,48,45);rect(159,133,6,2,55,48,45);}
static void street_art(void){int i;rect(0,58,320,164,27,13,35);rect(0,202,320,20,42,24,45);for(i=0;i<6;i++){int x=i*58-8;int h=48+(i%3)*14;rect(x,202-h,48,h,48,24,55);rect(x+7,164-h/2,8,11,115,50,78);rect(x+27,145-h/3,9,13,100,45,72);}rect(0,112,320,3,72,38,75);for(i=0;i<7;i++)rect(i*52+(anim_tick/5)%18,108,22,2,175,72,110);rect(145,176,18,46,170,45,65);rect(220,195,18,27,170,45,65);rect(70,190,14,14,switch_a?60:150,switch_a?210:60,70);rect(270,110,14,14,switch_b?60:150,switch_b?210:60,70);rect(hx(),142,16,8,220,70,80);if(!puzzle_done[1]){rect(pulse_x(1),124,12,5,225,75,105);rect(pulse_x(2),166,10,5,195,55,95);}}
static void house_art(void){int i;rect(0,58,320,164,11,29,29);rect(0,205,320,17,37,49,43);rect(16,72,288,8,30,58,52);for(i=0;i<4;i++){int x=28+i*76;rect(x,94,45,58,24,51,48);rect(x+5,99,35,48,42,75,67);rect(x+21,99,3,48,20,42,39);rect(x+5,121,35,3,20,42,39);}rect(45,82,30,20,70,125,110);rect(125,95,12,127,45,150,115);rect(260,130,12,92,45,150,115);rect(190,hy(),8,18,170,220,190);rect(88,178,60,5,65,88,72);rect(91,183,8,22,55,76,64);rect(137,183,8,22,55,76,64);if(!puzzle_done[2]){rect(156,62,4,70,160,205,180);rect(226,152,4,58,160,205,180);}}
static void clockworks_art(void){int i;rect(0,58,320,164,31,22,10);rect(0,210,320,12,62,43,20);for(i=0;i<7;i++){int x=12+i*48;int y=75+(i%2)*34;rect(x,y,30,30,72,49,22);rect(x+5,y+5,20,20,154,101,31);rect(x+13,y+2,4,26,47,31,15);rect(x+2,y+13,26,4,47,31,15);}for(i=0;i<6;i++)rect(i*58+(anim_tick/4)%22,134,34,4,122,76,24);rect(90,190,45,6,215,130,35);rect(200,110,45,6,215,130,35);rect(150,84,22,22,180,115,35);rect(hx(),160,20,6,240,145,35);rect(178,136,5,74,gameplay.dash_timer?70:235,gameplay.dash_timer?210:70,55);rect(238,62,5,94,gameplay.dash_timer?70:235,gameplay.dash_timer?210:70,55);}
static void chamber_art(void){int i,sx,p;rect(0,58,320,164,27,7,12);rect(0,210,320,12,52,19,25);for(i=0;i<6;i++){int x=22+i*54;rect(x,69,3,125,74,30,37);rect(x+3,72,18,3,74,30,37);}rect(104,70,112,92,43,19,28);rect(116,78,88,76,72,42,49);rect(128,82,64,64,90,55,65);rect(144,98,32,32,205,185,120);rect(158,88,4,42,60,45,42);rect(142,112,36,4,60,45,42);for(i=0;i<4;i++){sx=110+i*28;if(finale.socket[i]){p=(anim_tick/9+i)&3;rect(sx-2-p,153-p,16+p*2,16+p*2,22,90,105);rect(sx,155,12,12,90,235,250);}else{rect(sx-2,153,16,16,55,30,40);rect(sx,155,12,12,115,60,72);}}if(finale_hazard_active(&finale)){rect(finale_sweep_x(&finale),68,3,140,235,55,75);if(finale.phase==FINALE_STABILIZE)rect(28,finale_sweep_y(&finale),264,3,70,170,230);}if(finale.phase==FINALE_STABILIZE){rect(82,186,156,8,35,25,35);rect(84,188,(finale.stability*152)/100,4,75,220,235);}}
static void room_art(void){int i;if(room==0)station_art();else if(room==1)street_art();else if(room==2)house_art();else if(room==3)clockworks_art();else chamber_art();for(i=0;i<7;i++)rect((i*47+anim_tick/2)%320,68+((i*29+anim_tick/4)%132),1,1,70,75,100);echo_art();if(room<4&&!shard_taken[room]&&puzzle_done[room])draw_shard(250-room*35,90+room*28);draw_moko();}
static void collect_shard(uint16_t n){int sx,sy;if(room>=4||shard_taken[room]||!puzzle_done[room]||!pressed(n,PAD_CROSS))return;sx=250-room*35;sy=90+room*28;if(hit(px,py,12,18,sx-8,sy-9,25,31)){shard_taken[room]=1;shards++;gameplay_reward(&gameplay,250);gameplay_record_shard(&gameplay);score+=250+gameplay_score_bonus(&gameplay);checkpoint_room=room;checkpoint_score=score;checkpoint_time=timer_frames;sfx(0x2400);say(8);}}
static void memory_echo(uint16_t n){int ex,ey;if(room>=4||echo_seen[room]||!pressed(n,PAD_CROSS))return;ex=55+room*38;ey=112+room*17;if(hit(px,py,12,18,ex-10,ey-10,32,32)){echo_seen[room]=1;gameplay_reward(&gameplay,75);gameplay_record_echo(&gameplay);score+=75+gameplay_score_bonus(&gameplay);sfx(0x2000);say(10+room);}}
static int finale_interact(void){int i,sx;if(room!=4||shards<4)return 0;finale_begin(&finale,shards);if(finale.phase!=FINALE_RESTORE)return 0;for(i=0;i<4;i++){sx=110+i*28;if(!finale.socket[i]&&hit(px,py,12,18,sx-10,145,32,34)){if(finale_activate_socket(&finale,i,shards)){gameplay_reward(&gameplay,125);score+=125+gameplay_score_bonus(&gameplay);sfx(0x2000+i*0x300);if(finale.phase==FINALE_STABILIZE)say(15);return 1;}}}return 0;}
static void interact(uint16_t n){if(!pressed(n,PAD_CROSS))return;memory_echo(n);if(state!=STATE_PLAY)return;if(finale_interact())return;if(room==0&&hit(px,py,12,18,105,170,32,45)&&!puzzle_done[0]){puzzle_done[0]=1;gameplay_reward(&gameplay,100);score+=100+gameplay_score_bonus(&gameplay);sfx(0x1800);say(2);return;}if(room==1){if(hit(px,py,12,18,60,180,34,34)&&!switch_a){switch_a=1;gameplay_reward(&gameplay,50);score+=50+gameplay_score_bonus(&gameplay);sfx(0x1000);}if(hit(px,py,12,18,260,100,34,34)&&!switch_b){switch_b=1;gameplay_reward(&gameplay,50);score+=50+gameplay_score_bonus(&gameplay);sfx(0x1400);}if(switch_a&&switch_b&&!puzzle_done[1]){puzzle_done[1]=1;gameplay_reward(&gameplay,100);score+=100+gameplay_score_bonus(&gameplay);sfx(0x1a00);say(3);return;}}if(room==2&&hit(px,py,12,18,35,72,50,40)&&!puzzle_done[2]){if(shards>=2){puzzle_done[2]=1;gameplay_reward(&gameplay,150);score+=150+gameplay_score_bonus(&gameplay);sfx(0x1900);say(4);}else say(7);return;}if(room==3&&hit(px,py,12,18,140,74,42,42)&&!puzzle_done[3]){if(shards>=3){puzzle_done[3]=1;gameplay_reward(&gameplay,200);score+=200+gameplay_score_bonus(&gameplay);sfx(0x1c00);say(5);}else say(7);return;}collect_shard(n);}
static void hurt(void){if(invuln||gameplay.dash_timer>0)return;health--;score=score>=25?score-25:0;invuln=60;gameplay_break_combo(&gameplay);sfx(0x0700);px=30;py=190;if(health<=0){gameplay_record_death(&gameplay);state=STATE_GAMEOVER;}}
static void update_play(uint16_t n){int ox=px,oy=py,m=0,spd;last_room=room;if(pressed(n,PAD_R1)&&gameplay_try_dash(&gameplay))sfx(0x2b00);spd=gameplay_move_speed(&gameplay);if(!(n&PAD_LEFT)){px-=spd;facing=0;m=1;}if(!(n&PAD_RIGHT)){px+=spd;facing=1;m=1;}if(!(n&PAD_UP)){py-=spd;m=1;}if(!(n&PAD_DOWN)){py+=spd;m=1;}if(gameplay.dash_timer>0&&!m){px+=facing?spd:-spd;m=1;}if(m)walk_tick+=gameplay.dash_timer>0?2:1;else walk_tick=0;gameplay_tick(&gameplay,m);if(px<0){if(room>0){room--;px=306;sfx(0x0d00);}else px=0;}if(px>308){if(room<4){if(shard_taken[room]){room++;px=2;sfx(0x0d00);}else{px=308;if(pressed(n,PAD_CROSS))say(9);}}else px=308;}if(room!=last_room){area_banner=90;gameplay.room_time=0;moko_audio_set_room(room);if(room==4)finale_begin(&finale,shards);}if(py<62)py=62;if(py>204)py=204;if(room==1&&(hit(px,py,12,18,145,176,18,46)||hit(px,py,12,18,220,195,18,27))){px=ox;py=oy;}if(room==2&&(hit(px,py,12,18,125,95,12,127)||hit(px,py,12,18,260,130,12,92))){px=ox;py=oy;}if(room==2&&!puzzle_done[2]&&gameplay.dash_timer<=0&&(hit(px,py,12,18,156,62,4,70)||hit(px,py,12,18,226,152,4,58))){px=ox;py=oy;}if(room==3&&gameplay.dash_timer<=0&&(hit(px,py,12,18,178,136,5,74)||hit(px,py,12,18,238,62,5,94))){px=ox;py=oy;}interact(n);if(state!=STATE_PLAY)return;if(invuln>0)invuln--;if(room==1&&(hit(px,py,12,18,hx(),142,16,8)||(!puzzle_done[1]&&(hit(px,py,12,18,pulse_x(1),124,12,5)||hit(px,py,12,18,pulse_x(2),166,10,5)))))hurt();if(room==2&&hit(px,py,12,18,190,hy(),8,18))hurt();if(room==3&&(hit(px,py,12,18,90,184,45,18)||hit(px,py,12,18,hx(),160,20,6)))hurt();if(room==4){finale_tick(&finale,gameplay.dash_timer>0);if(finale_hazard_active(&finale)&&(hit(px,py,12,18,finale_sweep_x(&finale),68,3,140)||(finale.phase==FINALE_STABILIZE&&hit(px,py,12,18,28,finale_sweep_y(&finale),264,3))))hurt();if(finale_complete(&finale)){score+=finale_score_bonus(&finale)+timer_frames/60;sfx(0x2f00);state=STATE_ENDING;}}moko_audio_tick();if(pressed(n,PAD_START))state=STATE_PAUSE;if(timer_frames>0)timer_frames--;else{gameplay_record_death(&gameplay);state=STATE_GAMEOVER;}}
static void hud(void){static const char*n[]={"SILENT STATION","BACKWARD STREET","HOUSE WITHOUT MORNING","CLOCKWORKS","CLOCK CHAMBER"};int s=timer_frames/60;FntPrint(font_id,"%02d:%02d S%d/4 HP%d SCORE%d FOCUS%d\n%s R1:DASH COMBOx%d",s/60,s%60,shards,health,score,gameplay.focus,n[room],gameplay.combo);if(gameplay.dash_cooldown>0)FntPrint(font_id," CD%d",gameplay.dash_cooldown);if(room==4&&finale.phase==FINALE_RESTORE)FntPrint(font_id," RESTORE %d/4",finale.charge);else if(room==4&&finale.phase==FINALE_STABILIZE)FntPrint(font_id," STABILITY %d%%",finale.stability);if(area_banner>0){rect(62,76,196,22,5,7,15);FntPrint(font_id,"\n        %s",n[room]);}FntFlush(font_id);}
static void dialogue(void){room_art();rect(12,158,296,70,8,8,18);if(dialogue_id==1)FntPrint(font_id,"The hour was broken. Find what you forgot.\nR1 - MEMORY DASH");else if(dialogue_id==2)FntPrint(font_id,"The station clock wakes. A memory appears.");else if(dialogue_id==3)FntPrint(font_id,"Both signals glow. A memory is released.");else if(dialogue_id==4)FntPrint(font_id,"Morning returns. Another memory is free.");else if(dialogue_id==5)FntPrint(font_id,"The clockwork core reveals the final shard.");else if(dialogue_id==8)FntPrint(font_id,"MEMORY SHARD RECOVERED. CHECKPOINT SAVED.");else if(dialogue_id==9)FntPrint(font_id,"The way forward is sealed. Recover this memory.");else if(dialogue_id==10)FntPrint(font_id,"ECHO: A platform. A goodbye.\nYou promised you would come back.");else if(dialogue_id==11)FntPrint(font_id,"ECHO: The street ran backward,\nbut you kept walking away.");else if(dialogue_id==12)FntPrint(font_id,"ECHO: Morning never entered this house.\nSomeone was waiting for you.");else if(dialogue_id==13)FntPrint(font_id,"ECHO: The machine did not steal the hour.\nYou asked it to hide one.");else if(dialogue_id==15)FntPrint(font_id,"THE CLOCK IS AWAKE.\nDash through the fracture. Hold the hour together.");else FntPrint(font_id,"Recover the earlier memories first.");FntPrint(font_id,"\nCROSS - continue");FntFlush(font_id);}
int main(void){init();for(;;){uint16_t n=buttons();if(state==STATE_TITLE){rect(0,0,320,240,7,8,20);FntPrint(font_id,"\n\n      M O K O\n   THE LOST HOUR\n\n START - BEGIN\n Find four shards. Remember why.");FntFlush(font_id);if(pressed(n,PAD_START)||pressed(n,PAD_CROSS))reset_game();}else if(state==STATE_PLAY){update_play(n);room_art();hud();}else if(state==STATE_DIALOGUE){dialogue();if(pressed(n,PAD_CROSS))state=STATE_PLAY;}else if(state==STATE_PAUSE){room_art();FntPrint(font_id,"PAUSED SCORE %d FOCUS %d\nBEST COMBO x%d START - RESUME",score,gameplay.focus,gameplay.best_combo);FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_PLAY;}else if(state==STATE_GAMEOVER){rect(0,0,320,240,24,5,10);FntPrint(font_id,"\n THE HOUR IS LOST\n SCORE %d BEST x%d\n\nCROSS - CHECKPOINT\nSTART - NEW GAME",score,gameplay.best_combo);FntFlush(font_id);if(pressed(n,PAD_CROSS)){room=checkpoint_room;px=20;py=190;health=3;score=checkpoint_score;timer_frames=checkpoint_time>60*30?checkpoint_time:60*30;invuln=90;gameplay.focus=100;gameplay.dash_timer=0;gameplay.dash_cooldown=0;gameplay_break_combo(&gameplay);finale_reset(&finale);moko_audio_set_room(room);area_banner=90;state=STATE_PLAY;}if(pressed(n,PAD_START))reset_game();}else if(state==STATE_ENDING){rect(0,0,320,240,10,20,28);FntPrint(font_id,"\n THE LOST HOUR RETURNS\n\nMoko remembers:\nThe hour was hidden to escape a goodbye.\nRemembering hurts, but time can move again.\n\nSCORE %d BEST COMBO x%d\nECHOES %d/4 DEATHS %d\n\nCROSS - CREDITS",score,gameplay.best_combo,gameplay.echoes,gameplay.deaths);FntFlush(font_id);if(pressed(n,PAD_CROSS))state=STATE_CREDITS;}else{rect(0,0,320,240,4,4,10);FntPrint(font_id,"\n\n MOKO: THE LOST HOUR\n\n A game by ADSSS93\n Built for the original PlayStation\n\n Thank you for remembering.\n\n START - TITLE");FntFlush(font_id);if(pressed(n,PAD_START))state=STATE_TITLE;}old_btn=n;frame();}return 0;}